{
  "name": "gap_linear_normalized",
  "intuition": "Weights pairs by their positive objective gaps normalized per instance to emphasize pairs with larger relative gaps without complexity or imports.",
  "implementation_hint": {
    "expects": ["objective", "log_prob"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    b_idx, winner_idx, loser_idx = feature_cache['pair_idx']\n    objective = feature_cache['objective']\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap_positive = gap.clamp_min(0.0)\n    counts = torch.bincount(b_idx, minlength=objective.shape[0]).to(dtype=objective.dtype, device=objective.device)\n    sum_gap = torch.zeros(objective.shape[0], dtype=objective.dtype, device=objective.device)\n    sum_gap.index_add_(0, b_idx, gap_positive)\n    mean_gap = sum_gap / counts.clamp_min(1.0)\n    weight = gap_positive / mean_gap[b_idx].clamp_min(1e-6)\n    weight = weight.clamp_min(0.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})"
}
